export function createPlayerHand(THREE,camera){const g=new THREE.Group();g.position.set(.32,-.38,-.65);camera.add(g);g.visible=false;const elbow=new THREE.Group();g.add(elbow);const skin=new THREE.MeshPhysicalMaterial({color:0xc09378,roughness:.73,clearcoat:.04}),cloth=new THREE.MeshStandardMaterial({color:0x34423e,roughness:1});
 function part(parent,mat,x,y,z,sx,sy,sz){const m=new THREE.Mesh(new THREE.SphereGeometry(1,14,10),mat);m.position.set(x,y,z);m.scale.set(sx,sy,sz);parent.add(m);return m;}
 part(elbow,cloth,0,-.15,.08,.072,.22,.075);part(elbow,skin,0,.04,0,.055,.1,.06);part(elbow,skin,0,.12,-.035,.085,.09,.035);const fingers=[];
 for(let i=0;i<4;i++){const joint=new THREE.Group();joint.position.set((i-1.5)*.042,.17,-.04);elbow.add(joint);part(joint,skin,0,.03,-.035,.018,.02,.05);const tip=new THREE.Group();tip.position.set(0,.03,-.075);joint.add(tip);part(tip,skin,0,0,-.025,.016,.018,.037);part(joint,skin,0,.025,-.03,.02,.016,.021);part(tip,new THREE.MeshStandardMaterial({color:0xd8b5a0,roughness:.55}),0,.014,-.028,.01,.003,.016);fingers.push({joint,tip});}part(elbow,skin,-.09,.10,-.04,.024,.05,.025);
 const creases=new THREE.BufferGeometry();creases.setAttribute('position',new THREE.Float32BufferAttribute([-.055,.12,-.072,.04,.10,-.072,-.05,.08,-.068,.04,.07,-.068],3));elbow.add(new THREE.LineSegments(creases,new THREE.LineBasicMaterial({color:0x946e59,transparent:true,opacity:.4})));const cuff=new THREE.Mesh(new THREE.TorusGeometry(.072,.009,8,24),cloth);cuff.position.set(0,-.01,.035);cuff.rotation.x=Math.PI/2;elbow.add(cuff);const bound=g.clone(true);bound.position.x=-.32;bound.scale.x=-1;camera.add(bound);bound.visible=false;const silk=[];for(let i=0;i<13;i++){const y=-.08+i*.018;silk.push(-.12,y,-.06,.12,y+.04,.04);}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.Float32BufferAttribute(silk,3));const material=new THREE.LineBasicMaterial({color:0xbcc6bb,transparent:true,opacity:.8});const web=new THREE.LineSegments(geo,material);elbow.add(web);web.visible=false;const leftWeb=web.clone();leftWeb.visible=true;bound.add(leftWeb);
 return{g,point(){g.visible=true;bound.visible=false;web.visible=false;elbow.rotation.x=0;fingers.forEach((f,i)=>{f.joint.rotation.x=i===1?0:-.8;f.tip.rotation.x=i===1?0:-1;});},grip(amount=1){g.visible=true;bound.visible=false;web.visible=false;elbow.rotation.x=0;for(const f of fingers){f.joint.rotation.x=-amount*.55;f.tip.rotation.x=-amount*1.05;}},defend(u){const lift=Math.max(0,Math.min(1,u));g.visible=true;bound.visible=true;web.visible=false;leftWeb.visible=false;g.position.set(.27,-.42+lift*.3,-.52);bound.position.set(-.27,g.position.y,-.52);elbow.rotation.x=-.1-lift*.4;g.rotation.z=-lift*.18;bound.rotation.z=lift*.18;},reset(){g.rotation.set(0,0,0);g.visible=false;g.position.set(.32,-.38,-.65);elbow.rotation.x=0;bound.visible=false;web.visible=false;},pose(u){g.visible=true;const reach=Math.sin(Math.PI*u);g.position.y=-.38-reach*.14;elbow.rotation.x=-reach*.7;for(const f of fingers){f.joint.rotation.x=-Math.min(1,u*3)*.65;f.tip.rotation.x=-Math.min(1,u*3)*.85;}},caught(t){g.visible=true;bound.visible=true;web.visible=true;g.position.set(.3,-.28+Math.sin(t*3)*.012,-.65);bound.position.y=g.position.y;elbow.rotation.x=-.3;}};
}
